"use client"

import React, { useEffect, useRef, useState } from "react"
// Generated by scripts/generate-image-placeholders.mjs before every dev/build
import placeholders from "@/lib/image-placeholders.json"

type Placeholder = { w: number; h: number; blur: string }
const PLACEHOLDERS = placeholders as Record<string, Placeholder>

// "loading"  → the blurred placeholder shows (as the <img>'s own background)
// "focusing" → the real image has arrived and sharpens from blurred
// "done"     → a plain <img>
type Stage = "loading" | "focusing" | "done"

/**
 * Drop-in replacement for <img> on case study pages. While the image
 * downloads, it shows a blurred mini version of it; once loaded, the image
 * comes into focus. Images without a placeholder (transparent logos, anything
 * outside public/images/projects) render as a plain <img>.
 *
 * Why the placeholder is a CSS background on the <img> itself, not a separate
 * element behind it: no wrapper means every class the page already puts on
 * the <img> (w-full, rounded-lg, mb-4…) keeps working unchanged. A loading
 * <img> shows its background; once the picture arrives it paints on top.
 */
export function CaseStudyImage({ src, style, onLoad, ...rest }: React.ImgHTMLAttributes<HTMLImageElement>) {
  const placeholder = typeof src === "string" ? PLACEHOLDERS[src] : undefined
  const ref = useRef<HTMLImageElement>(null)
  const [stage, setStage] = useState<Stage>("loading")
  const [radius, setRadius] = useState("0px")

  // The page is pre-rendered to HTML, so the image can finish loading before
  // React attaches onLoad. If it's already there (or was cached), skip
  // straight to "done": no placeholder, no focus animation.
  // 📖 Learn: HTMLImageElement.complete, hydration
  useEffect(() => {
    const img = ref.current
    if (img?.complete && img.naturalWidth > 0) setStage("done")
  }, [src])

  const handleLoad = (event: React.SyntheticEvent<HTMLImageElement>) => {
    // clip-path below needs the image's own corner radius
    setRadius(getComputedStyle(event.currentTarget).borderRadius || "0px")
    setStage((current) => (current === "loading" ? "focusing" : current))
    onLoad?.(event)
  }

  if (!placeholder) {
    return <img src={src} style={style} onLoad={onLoad} {...rest} />
  }

  const stageStyle: React.CSSProperties =
    stage === "loading"
      ? {
          backgroundImage: `url("${placeholder.blur}")`,
          backgroundSize: "cover", // matches object-cover images; full-width images are the same shape anyway
          backgroundPosition: "center",
        }
      : stage === "focusing"
        ? {
            animation: "case-study-image-focus 350ms ease-out",
            // blur() bleeds a soft halo outside the box; clip-path is applied
            // after filters, so this trims it back to the image's shape.
            // 📖 Learn: CSS filter vs clip-path order
            clipPath: `inset(0 round ${radius})`,
          }
        : {}

  return (
    <img
      ref={ref}
      src={src}
      data-case-study-image // lets globals.css turn the focus animation off for Reduce Motion
      onLoad={handleLoad}
      onAnimationEnd={() => setStage("done")}
      style={{
        // Reserves the right-shaped box before the image arrives, so the
        // placeholder has something to fill and the text below doesn't jump.
        // "auto" = once loaded, the real image's own shape takes over.
        // 📖 Learn: CSS aspect-ratio
        aspectRatio: `auto ${placeholder.w} / ${placeholder.h}`,
        ...stageStyle,
        ...style, // the page's own inline styles still win
      }}
      {...rest}
    />
  )
}
